const flashcardsTO: { cat: string; q: string; a: string }[] = [{"cat": "Fundamentos da Gastronomia", "q": "Qual é a função central da mise en place?", "a": "Organizar ingredientes, utensílios e etapas antes da execução para reduzir falhas e interrupções."}, {"cat": "Fundamentos da Gastronomia", "q": "O que é comensalidade?", "a": "É o conjunto de práticas sociais ligadas a compartilhar comida, mesa, regras e ocasiões de comer."}, {"cat": "Fundamentos da Gastronomia", "q": "O que acontece na gelatinização do amido?", "a": "O amido absorve água e incha com o calor, aumentando a viscosidade do sistema."}, {"cat": "Fundamentos da Gastronomia", "q": "Como se calcula o fator de correção?", "a": "Peso bruto dividido pelo peso líquido após limpeza e seleção."}, {"cat": "Fundamentos da Gastronomia", "q": "Qual é a principal função energética dos carboidratos?", "a": "Fornecer glicose e energia para diferentes tecidos e atividades do organismo."}, {"cat": "Fundamentos da Gastronomia", "q": "Para que serve um teste triangular?", "a": "Para verificar se existe diferença sensorial perceptível entre amostras."}, {"cat": "Técnicas de Cozinha", "q": "Por que cortes uniformes favorecem a cocção?", "a": "Porque peças de tamanho semelhante recebem calor em velocidades mais próximas."}, {"cat": "Técnicas de Cozinha", "q": "Quando um braseado é especialmente adequado?", "a": "Para peças com mais tecido conjuntivo, que se beneficiam de tempo, umidade e calor moderado."}, {"cat": "Técnicas de Cozinha", "q": "Por que cozinha fria exige atenção sanitária intensa?", "a": "Porque muitas preparações não recebem uma cocção final antes de serem consumidas."}, {"cat": "Técnicas de Cozinha", "q": "Por que cortes ricos em colágeno aceitam cocção longa?", "a": "Porque tempo e umidade favorecem a conversão do colágeno em gelatina."}, {"cat": "Técnicas de Cozinha", "q": "Por que pescados ressecam com facilidade?", "a": "Suas proteínas coagulam rapidamente e muitas espécies têm pouca gordura intramuscular."}, {"cat": "Técnicas de Cozinha", "q": "O que o branqueamento faz com vegetais?", "a": "Aplica cocção breve seguida de resfriamento rápido, controlando textura, cor e processo."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Qual é a função da rede de glúten no pão?", "a": "Reter gases da fermentação e sustentar a estrutura durante crescimento e forno."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "O que diferencia crème anglaise de crème pâtissière?", "a": "O pâtissière contém amido e fica mais espesso; o anglaise é espessado principalmente por gemas."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Para que serve a temperagem do chocolate?", "a": "Para formar cristais estáveis de manteiga de cacau, favorecendo brilho, quebra e contração."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Por que acidez pode equilibrar uma sobremesa doce?", "a": "Porque cria contraste sensorial e reduz a percepção de doçura excessiva."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "O que acontece em uma subextração de café?", "a": "Poucos compostos são extraídos, frequentemente resultando em acidez agressiva e baixa doçura."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Qual componente do vinho ajuda a equilibrar pratos gordurosos?", "a": "A acidez, por aumentar frescor e limpar a sensação de gordura."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Por que a mandioca é central em muitas cozinhas brasileiras?", "a": "Porque gera farinhas, goma, polvilhos, tucupi e inúmeras preparações regionais."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Qual ingrediente liga muitas cozinhas amazônicas a saberes indígenas?", "a": "A mandioca e seus derivados, além de pescados e ingredientes florestais."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Qual é a base de um béchamel clássico?", "a": "Leite espessado com roux."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "O que significa mantecare um risotto?", "a": "Finalizar fora ou quase fora do fogo com gordura e, frequentemente, queijo para criar textura cremosa."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "O que é umami?", "a": "Um gosto básico associado principalmente ao glutamato e intensificado por alguns nucleotídeos."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Como compreender cozinhas mexicanas e nixtamalização?", "a": "Milho, pimentas, feijões, ervas e técnicas ancestrais estruturam muitas cozinhas mexicanas. Nixtamalização trata milho em meio alcalino, alterando textura, sabor, funcionalidade e disponibilidade de nutrientes."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "O que é contaminação cruzada?", "a": "Transferência de perigos entre alimentos, mãos, superfícies, utensílios ou ambientes."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Vírus se multiplicam nos alimentos?", "a": "Não. Alimentos podem veiculá-los, mas a replicação viral depende de células hospedeiras."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Para que serve um POP?", "a": "Para descrever de forma padronizada como uma tarefa deve ser executada, monitorada e registrada."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "O que é um ponto crítico de controle?", "a": "Etapa em que o controle é essencial para prevenir, eliminar ou reduzir um perigo significativo."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Por que a legislação deve ser consultada em fonte oficial?", "a": "Porque normas podem ser atualizadas e exigências variam por escopo e localidade."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Qual é a primeira estratégia contra desperdício?", "a": "Prevenir a geração, ajustando compras, armazenamento, produção e porcionamento."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "O que é um gargalo operacional?", "a": "É um ponto cuja capacidade limita o fluxo ou a produtividade do processo inteiro."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "Qual é uma fórmula básica de CMV?", "a": "Estoque inicial + compras - estoque final."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "O que cruza a engenharia de cardápio?", "a": "Popularidade de venda e margem de contribuição dos itens."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "O que é lead time de fornecedor?", "a": "O tempo entre emitir o pedido e receber o item disponível para uso."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "Por que o tipo de serviço altera o dimensionamento?", "a": "Porque buffet, empratado e volante geram consumos, tempos e equipes diferentes."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "Qual é a diferença entre lucro e fluxo de caixa?", "a": "Lucro é resultado econômico; fluxo de caixa acompanha entradas e saídas efetivas de dinheiro."}, {"cat": "Gestão, Eventos e Formação Acadêmica", "q": "Como compreender problema, objetivos e justificativa?", "a": "Problema de pesquisa deve ser claro, delimitado e investigável. Objetivo geral expressa o principal resultado pretendido e objetivos específicos dividem o percurso em etapas. Justificativa explica relevância acadêmica, social ou profissional."}, {"cat": "Fundamentos da Gastronomia", "q": "O que a brigada de cozinha organiza?", "a": "Responsabilidades, comunicação e divisão de trabalho entre funções e praças da cozinha."}, {"cat": "Fundamentos da Gastronomia", "q": "Por que um prato pode expressar identidade cultural?", "a": "Porque reúne ingredientes, técnicas, memórias, território e significados compartilhados por um grupo."}, {"cat": "Fundamentos da Gastronomia", "q": "Qual é a diferença entre Maillard e caramelização?", "a": "Maillard envolve compostos carbonílicos e grupos amino; caramelização envolve açúcares aquecidos."}, {"cat": "Fundamentos da Gastronomia", "q": "Por que o rendimento deve ser medido após o preparo?", "a": "Porque cocção e pré-preparo alteram massa, volume e número real de porções."}, {"cat": "Fundamentos da Gastronomia", "q": "O que é biodisponibilidade?", "a": "É a proporção de um nutriente que fica disponível para absorção e utilização pelo organismo."}, {"cat": "Fundamentos da Gastronomia", "q": "O que mede uma escala hedônica?", "a": "O grau de aceitação ou agrado do consumidor em relação a uma amostra."}, {"cat": "Técnicas de Cozinha", "q": "O que significa deglaçar uma panela?", "a": "Adicionar líquido para dissolver o fundo aderido e incorporar seus compostos de sabor."}, {"cat": "Técnicas de Cozinha", "q": "Por que panela lotada reduz o douramento?", "a": "Porque libera muita água e derruba a temperatura, favorecendo vapor em vez de Maillard."}, {"cat": "Técnicas de Cozinha", "q": "O que diferencia vinagrete de maionese?", "a": "Vinagrete é emulsão pouco estável; maionese é estabilizada principalmente pela lecitina da gema."}, {"cat": "Técnicas de Cozinha", "q": "Selar uma carne fecha os poros?", "a": "Não. A selagem desenvolve cor e sabor, mas não cria uma barreira impermeável."}, {"cat": "Técnicas de Cozinha", "q": "Qual é a utilidade culinária de espinhas e cabeças adequadas?", "a": "Podem compor fumets e bases de sabor quando frescas e próprias para esse uso."}, {"cat": "Técnicas de Cozinha", "q": "Por que ácidos podem retardar o amolecimento de leguminosas?", "a": "Porque influenciam estruturas da parede celular e dificultam sua desorganização."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Na porcentagem do padeiro, qual ingrediente vale 100%?", "a": "A farinha total da fórmula."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Qual é a principal diferença entre merengue francês e italiano?", "a": "O italiano recebe calda quente; o francês incorpora açúcar diretamente às claras batidas."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "O que é fat bloom?", "a": "É o esbranquiçamento causado por migração ou cristalização instável da gordura."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Qual é um cuidado central em construção de uma sobremesa equilibrada?", "a": "Acidez pode equilibrar doçura."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Como a moagem afeta a extração?", "a": "Moagem mais fina aumenta área de contato e resistência ao fluxo, alterando a velocidade de extração."}, {"cat": "Panificação, Confeitaria e Bebidas", "q": "Por que vinho muito frio parece menos aromático?", "a": "Porque temperaturas baixas reduzem a volatilização de compostos aromáticos."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Por que não existe uma única cozinha brasileira?", "a": "Porque biomas, povos, migrações, economias e territórios formaram repertórios regionais distintos."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "O que diferencia cozinhas sertanejas e litorâneas no Nordeste?", "a": "Ambiente, disponibilidade de ingredientes, conservação e presença de pescados, coco ou produtos do semiárido."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "O que é um velouté?", "a": "Molho feito a partir de fundo claro espessado com roux."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Por que finalizar massa no molho melhora o prato?", "a": "Porque integra amido, molho e gordura, melhorando aderência e emulsão."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Por que mise en place é essencial no wok?", "a": "Porque a cocção pode ser extremamente rápida e não permite preparar ingredientes durante o processo."}, {"cat": "Cozinhas do Brasil e do Mundo", "q": "Qual é um cuidado central em cozinhas mexicanas e nixtamalização?", "a": "Tortilla tradicional depende de masa nixtamalizada."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Por que lavar as mãos não é substituído pelo uso de luvas?", "a": "Porque luvas também contaminam e precisam ser usadas dentro de um procedimento correto."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Qual é a diferença entre infecção e intoxicação alimentar?", "a": "Na infecção ingere-se o agente vivo; na intoxicação ingere-se toxina já formada no alimento."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "O que significa PVPS no estoque?", "a": "Primeiro que vence, primeiro que sai."}, {"cat": "Segurança, Qualidade e Sustentabilidade", "q": "Qual é um cuidado central em princípios do appcc?", "a": "Identificar perigos e medidas de controle."}];

